// Title: Apply list‑type data validation to cells generated by smart markers using Aspose.Cells for .NET
// AI Prompts: Create a workbook with a smart marker that fills product names from a C# collection, then attach a drop‑down list validation to the populated cells. | After WorkbookDesigner.Process, add a Validation of type List for the smart‑marker range and set Formula1 to a comma‑separated list of allowed values. | Save the workbook and verify that each cell filled by the smart marker shows a selectable list of products.
// Common Searches: aspocells add drop‑down list validation after smart marker processing c# | how to restrict smart marker output to predefined values in Aspose.Cells | c# apply data validation to cells filled by smart markers Aspose.Cells example | list validation for generated rows using Aspose.Cells WorkbookDesigner
// Tags: smart markers list validation Aspose.Cells | apply drop‑down validation to generated cells C# | Aspose.Cells validation collection example | list‑type validation formula1 usage | data validation after smart marker processing

using System;
using System.Collections.Generic;
using System.IO;
using Aspose.Cells;

// The sample creates a workbook, defines a smart marker in A2, processes it with a list of Product objects, then adds a list‑type data validation (Apple,Orange,Banana) to the cells populated by the smart marker (A2:A4) and saves the file.
public class SmartMarkerValidationDemo
{
    public static void Run()
    {
        try
        {
            // Create a new workbook that will serve as the template
            Workbook wb = new Workbook();
            Worksheet ws = wb.Worksheets[0];

            // Header cell
            ws.Cells["A1"].PutValue("Product");

            // Smart marker that will be replaced by the data source value
            ws.Cells["A2"].PutValue("&=$ProductName");

            // Define the range that contains smart markers and give it the required name
            Aspose.Cells.Range smRange = ws.Cells.CreateRange("A2:A2");
            smRange.Name = "_CellsSmartMarkers";

            // Prepare a simple data source (list of objects)
            List<Product> products = new List<Product>
            {
                new Product { ProductName = "Apple" },
                new Product { ProductName = "Orange" },
                new Product { ProductName = "Banana" }
            };

            // Set up the WorkbookDesigner with the workbook and data source
            WorkbookDesigner designer = new WorkbookDesigner
            {
                Workbook = wb
            };
            designer.SetDataSource("Data", products);

            // Process the smart markers – cells are now populated with product names
            designer.Process();

            // After processing, apply data validation to the cells that were filled
            // The data will occupy rows 2‑4 in column A (zero‑based indices 1‑3, column 0)
            ValidationCollection validations = ws.Validations;
            CellArea validationArea = CellArea.CreateCellArea(1, 0, 3, 0);
            int validationIndex = validations.Add(validationArea);
            Validation validation = validations[validationIndex];

            // Configure the validation to allow only the predefined list of products
            validation.Type = ValidationType.List;
            validation.Formula1 = "Apple,Orange,Banana";
            validation.InCellDropDown = true;
            validation.ShowInput = true;
            validation.InputTitle = "Select Product";
            validation.InputMessage = "Choose a product from the list.";
            validation.ShowError = true;
            validation.ErrorTitle = "Invalid Product";
            validation.ErrorMessage = "Please select a product from the predefined list.";

            // Save the resulting workbook
            string outputPath = "SmartMarkerWithValidation.xlsx";
            wb.Save(outputPath);
            Console.WriteLine($"Workbook saved to {Path.GetFullPath(outputPath)}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }

    // Simple POCO class used as the data source for the smart marker
    public class Product
    {
        public string? ProductName { get; set; }
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        SmartMarkerValidationDemo.Run();
    }
}
